import re, sys
pat = re.compile(r'js-sources-check|js-cite-check|REGRESSION|--regression|mkdir|open\(|write|rm -rf|kumitate|sibling|LANE|-C |/\.\./|git -C|git --git-dir|\bcp\b|sed -i|> ')
for a in sys.argv[1:]:
    p, _, r = a.partition(':')
    lo, hi = ((int(x) for x in r.split('-')) if r else (1, 10**9))
    print('=== ' + a)
    for i, l in enumerate(open(p, encoding='utf-8'), 1):
        if lo <= i <= hi and (r or pat.search(l)):
            print(str(i) + '\t' + l.rstrip('\n')[:260])
